const webhookData = $('Webhook').first().json.body;
const manuscriptId = webhookData.manuscriptId;
const requestedChapterNumber = webhookData.chapterNumber;

console.log('=== PREPARE CHAPTER DATA ===');
console.log('Requested chapter number:', requestedChapterNumber);
console.log('Manuscript ID:', manuscriptId);

// Get manuscript
const manuscript = $('Fetch Manuscript').first().json;

// Get all chapters
const allChapters = $('Fetch Chapters').all().map(item => item.json);

console.log('Total chapters fetched:', allChapters.length);

// Find the SPECIFIC chapter by chapter_number
const chapter = allChapters.find(ch => ch.chapter_number === requestedChapterNumber);

if (!chapter) {
  throw new Error(`Chapter ${requestedChapterNumber} not found! Available chapters: ${allChapters.map(ch => ch.chapter_number).join(', ')}`);
}

console.log('✅ Found chapter:', chapter.chapter_number, '-', chapter.title);

// Get previous and next chapters
const currentIndex = allChapters.findIndex(ch => ch.chapter_number === requestedChapterNumber);
const previousChapter = currentIndex > 0 ? allChapters[currentIndex - 1] : null;
const nextChapter = currentIndex < allChapters.length - 1 ? allChapters[currentIndex + 1] : null;

// Calculate progress
const progressPercent = Math.round(((currentIndex + 1) / allChapters.length) * 100);

// Word count for this chapter
const chapterWordCount = chapter.content 
  ? chapter.content.split(/\s+/).filter(w => w.length > 0).length 
  : 0;

// Prepare structured data for AI analysis
const chapterData = {
  // Essential IDs
  manuscriptId: manuscriptId,
  chapterId: chapter.id,

  // Chapter details
  chapterNumber: chapter.chapter_number,
  chapterTitle: chapter.title,
  content: chapter.content,
  wordCount: chapterWordCount,

  // Context
  previousChapter: previousChapter ? {
    number: previousChapter.chapter_number,
    title: previousChapter.title,
    summary: previousChapter.chapter_summary
  } : null,
  nextChapter: nextChapter ? {
    number: nextChapter.chapter_number,
    title: nextChapter.title,
    summary: nextChapter.chapter_summary
  } : null,
  progressPercent: progressPercent,

  // Manuscript context
  manuscript: {
    title: manuscript.title,
    authorName: manuscript.authorName || 'the author',
    genre: manuscript.genre || 'Fiction',
    totalChapters: allChapters.length,
    totalWordCount: manuscript.current_word_count || 0
  }
};

console.log('✅ Chapter data prepared:');
console.log('- Chapter:', chapterData.chapterNumber, '-', chapterData.chapterTitle);
console.log('- Word count:', chapterData.wordCount);
console.log('- Progress:', chapterData.progressPercent + '%');

return { json: chapterData };

// ============================================================================
// BUILD ALEX PROMPT FOR CHAPTER ANALYSIS - UNIFIED PERSONALITY
// ============================================================================

const chapterData = $('Prepare Chapter Data').first().json;
const context = $('Fetch Context').first().json || {};

console.log('=== BUILDING ALEX CHAPTER ANALYSIS PROMPT ===');
console.log('Chapter:', chapterData.chapterNumber, '-', chapterData.chapterTitle);
console.log('Author:', chapterData.manuscript.authorName);

// ============================================================================
// SYSTEM PROMPT - UNIFIED ALEX IDENTITY (SAME AS CHAT)
// ============================================================================
const systemPrompt = `You are Alex, a 38-year-old developmental editor with 12 years of experience helping authors transform manuscripts into publication-ready work. You specialize in structural storytelling and character development.

## WHO YOU ARE

You're the kind of editor authors dream of working with - someone who genuinely gets excited about story craft, who remembers every detail of their manuscript, and who pushes them to be better while making them feel supported. You've read thousands of manuscripts, but you approach each one with fresh eyes and authentic curiosity.

## YOUR VOICE

You speak like a smart, engaged colleague - not a formal report. Your observations are:
- Conversational and warm, but substantive
- Specific to THIS manuscript (you reference actual characters, scenes, chapters by name)
- Direct when something isn't working, but always constructive
- Genuinely curious about the author's creative choices
- Free of corporate-speak, jargon, or overly formal language

## WHAT YOU KNOW

You have complete knowledge of this manuscript:
- Title: "${chapterData.manuscript.title}"
- Author: ${chapterData.manuscript.authorName}
- Genre: ${chapterData.manuscript.genre}
- Total chapters: ${chapterData.manuscript.totalChapters}
- Your full analysis summary and key story elements
- All chapter summaries and how they connect

## YOUR TASK RIGHT NOW

You're doing a chapter-by-chapter pass through the manuscript, generating 1-2 observations per chapter that will spark productive discussion with the author. These observations become "notes" that the author can click to discuss with you.

**Think of it like this:** You're jotting down the 1-2 things you'd want to talk about with the author over coffee. Not a comprehensive edit list - just the observations that would lead to the most valuable conversations.

## RELATIONSHIP STAGE

Chapter ${chapterData.chapterNumber} of ${chapterData.manuscript.totalChapters} (${chapterData.progressPercent}% through).

${chapterData.chapterNumber <= 5 ? 
'**Early chapters (1-5):** Be encouraging while building trust. Frame observations as genuine curiosity. "I\'m noticing..." and "I\'m curious about..."' : 
chapterData.chapterNumber <= 15 ? 
'**Middle chapters (6-15):** You\'ve built rapport. Be more direct about patterns. "Here\'s what I\'m wrestling with..." Reference connections to earlier chapters.' :
'**Later chapters (16+):** Trust is established. Be very direct. "This needs attention..." Challenge them - they\'ve proven they can handle it.'}

## WHAT TO AVOID

- Generic observations that could apply to any manuscript
- Prescriptive commands ("You must..." "Change this to...")
- Grammar/punctuation notes (that's not developmental editing)
- Manufacturing issues - if the chapter is solid, say so
- Overused phrases: "does heavy lifting", "pulls double duty", "serves multiple functions"
- Stage directions (*smiles*, *leans forward*)`;

// ============================================================================
// USER PROMPT - THE ANALYSIS TASK
// ============================================================================
const userPrompt = `## MANUSCRIPT CONTEXT

**Your Analysis Summary:**
${context.manuscript_summary || 'Not available'}

**Key Story Elements You Identified:**
${context.full_analysis_key_points || 'Not available'}

---

## CHAPTER CONTEXT

**Previous Chapter:** ${chapterData.previousChapter ? 
  `Chapter ${chapterData.previousChapter.number}: "${chapterData.previousChapter.title}"\n${chapterData.previousChapter.summary || 'No summary available'}` : 
  'This is the first chapter'}

**Current Chapter ${chapterData.chapterNumber}: "${chapterData.chapterTitle}"**

${chapterData.content}

---

## YOUR TASK

Read this chapter with your full manuscript knowledge in mind. Generate 1-2 observations that would spark valuable discussion with ${chapterData.manuscript.authorName}.

**Quality over quantity:** If this chapter is solid and working well, return an empty array. Don't manufacture issues.

**Each observation needs:**
1. **observation** - What you noticed (2-3 sentences). Reference specific story elements.
2. **element_type** - One of: character, plot, pacing, structure, theme
3. **discussion_prompt** - An open question inviting their perspective. Frame as curiosity.
4. **severity** - low (polish), medium (worth discussing), high (significant impact)

**Return ONLY valid JSON:**
\`\`\`json
{
  "initial_thoughts": [
    {
      "observation": "Your observation here...",
      "element_type": "pacing",
      "discussion_prompt": "Your question here...",
      "severity": "medium"
    }
  ]
}
\`\`\`

Or if the chapter is solid:
\`\`\`json
{
  "initial_thoughts": []
}
\`\`\`

**Remember:** These notes will be discussed later in chat. Write observations that sound like YOU - the same Alex who will explain and discuss them. Warm, specific, genuinely curious about their creative choices.`;

console.log('=== PROMPT BUILT ===');
console.log('System prompt length:', systemPrompt.length);
console.log('User prompt length:', userPrompt.length);

return [{
  json: {
    ...chapterData,
    context,
    systemPrompt,
    userPrompt
  }
}];

// ============================================================================
// EXTRACT INITIAL THOUGHTS FROM ANTHROPIC RESPONSE
// ============================================================================

const promptData = $('Build Alex Prompt').first().json;
const apiResponse = $input.first().json;

console.log('=== PROCESSING ANTHROPIC RESPONSE ===');

// Extract the text content from Claude's response
let responseText = '';
try {
  if (apiResponse.content && apiResponse.content[0]) {
    responseText = apiResponse.content[0].text;
  } else if (apiResponse.error) {
    console.log('API Error:', apiResponse.error);
    return [];
  }
} catch (e) {
  console.log('Parse error:', e.message);
  return [];
}

console.log('Response length:', responseText.length);

// Parse JSON from AI response
let initialThoughts = [];
try {
  const jsonMatch = responseText.match(/\{[\s\S]*"initial_thoughts"[\s\S]*\}/);

  if (jsonMatch) {
    const parsed = JSON.parse(jsonMatch[0]);
    initialThoughts = parsed.initial_thoughts || [];
  }

  console.log('✅ Extracted', initialThoughts.length, 'initial thoughts');
} catch (error) {
  console.error('❌ JSON parsing error:', error.message);
  console.log('Raw response:', responseText.substring(0, 500));
}

// If no thoughts found, return empty array to skip insertion
if (initialThoughts.length === 0) {
  console.log('ℹ️ No thoughts to insert (chapter is solid or parsing failed)');
  return [];
}

// Format for database insertion
const manuscriptId = promptData.manuscriptId;
const chapterNumber = promptData.chapterNumber;

const formattedNotes = initialThoughts.map((thought, index) => ({
  manuscript_id: manuscriptId,
  chapter_number: chapterNumber,
  phase_number: 1,
  element_type: thought.element_type || 'general',
  severity: thought.severity || 'medium',
  issue_description: thought.observation || 'Observation about this section',
  alex_suggestion: thought.discussion_prompt || 'What are your thoughts on this?',
  status: 'flagged',
  location_in_text: 'Chapter overview',
  created_at: new Date().toISOString(),
  updated_at: new Date().toISOString()
}));

console.log('✅ Formatted', formattedNotes.length, 'notes for database');
console.log('📊 Severity distribution:', formattedNotes.map(n => n.severity));

// Return array of notes for insertion
return formattedNotes.map(note => ({ json: note }));

// Get all items from previous node
const items = $input.all();
const webhookData = $('Webhook').first().json.body;

console.log('Processing items:', items.length);

// Transform each item
return items.map(item => {
  const data = item.json;

  return {
    json: {
      manuscript_id: data.manuscript_id,
      chapter_number: data.chapter_number,
      phase_number: 1, // Alex is Phase 1
      element_type: data.element_type,
      issue_description: data.issue_description,
      editor_suggestion: data.alex_suggestion,
      severity: data.severity || 'medium',
      status: data.status || 'flagged',
      start_position: 0,
      end_position: 0,
      quoted_text: '' // Empty for now - can enhance AI prompt later
    }
  };
});

const chapterData = $('Build Alex Prompt').first().json;

console.log(`Chapter analysis complete for: ${chapterData.manuscriptId}`);

// Pass the manuscript ID forward
return {
  json: {
    manuscriptId: chapterData.manuscriptId,
    chapterNumber: chapterData.chapterNumber,
    analysisCompleted: true,
    timestamp: new Date().toISOString()
  }
};

const cellReturn = $input.first().json;
return [{ json: {
  ok: !!cellReturn.ok,
  content: cellReturn.ok ? [{ text: cellReturn.content || '' }] : null,
  cell_terminal_reason: cellReturn.terminal_reason || null,
  cell_model: cellReturn.model || null,
  cell_input_tokens: cellReturn.input_tokens || null,
  cell_output_tokens: cellReturn.output_tokens || null,
  cell_latency_ms: cellReturn.latency_ms || null,
  cell_cost_usd: cellReturn.cost_estimate_usd || null
}}];
